"use client";

import { useEffect, useRef, useState } from "react";

/**
 * The hero circuit. Current runs the network and each block lights AS THE
 * CURRENT ENTERS IT.
 *
 * WHY THE MARKUP IS A MAP OVER DATA
 *   Earlier versions of this file were generated by a script that pasted
 *   markup into a template. Three separate faults came out of that and none
 *   of them were design problems: a selector that matched nothing, CSS
 *   variables nothing defined, and a placeholder collision that wrote the
 *   number 3800 where the wires should have been. The geometry below is
 *   data; everything else is written once, by hand.
 *
 * THE SEQUENCE
 *   Wires carry the millisecond they start. A stage never begins until the
 *   block it feeds has lit, so the current cannot appear to pass through a
 *   dark block:
 *
 *     feeds   0 →  600   enter the first block at 1200
 *     middle  1900 → 2500   enter the second at 3100
 *     out     3800 → 4400   enter the third at 5000
 *     trail   5700         last arrival 6900
 */

const TRAVEL = 1200;   // current crossing one wire
const DASH = 0.55;     // how much of a wire is lit at once, as a fraction
const RISE = 700;      // light filling a block
const HOLD = 1800;     // everything lit
const FADE = 550;      // letting go
const REST_MS = 3800;  // empty circuit before it runs again

/** The instant current ENTERS each block, in the order they are drawn. */
const BLOCK_AT = [1200, 3100, 5000];
const LAST = 6900;
const CYCLE = LAST + HOLD + FADE + REST_MS;

const WIRES = [
  { at: 0, c: "#0077B6", d: "M 35.6 108.5 L 91.6 140.8 Q 97.5 144.2 103.3 140.8 L 130.2 125.3 Q 136.1 121.9 142.0 125.3 L 190.2 153.1" },
  { at: 300, c: "#0077B6", d: "M 89.7 77.3 L 145.7 109.6 Q 151.5 113.0 145.7 116.4 L 136.1 121.9" },
  { at: 600, c: "#0077B6", d: "M 26.0 181.0 L 56.9 163.2 Q 62.7 159.8 68.6 163.2 L 87.7 174.3 Q 93.6 177.7 99.5 174.3 L 137.9 152.1 Q 143.8 148.7 149.7 152.1 L 170.9 164.3" },
  { at: 1900, c: "#00A859", d: "M 228.8 175.4 L 249.9 187.6 Q 255.9 191.0 261.8 187.6 L 288.6 172.1 Q 294.4 168.7 300.4 172.1 L 325.4 186.6" },
  { at: 2200, c: "#00A859", d: "M 209.5 186.6 L 230.6 198.8 Q 236.6 202.2 230.6 205.6 L 199.9 223.3 Q 194.1 226.7 199.9 230.1 L 236.6 251.3" },
  { at: 2500, c: "#00A859", d: "M 244.3 166.5 L 253.8 172.0 Q 259.7 175.4 265.6 172.0 L 315.7 143.1 Q 321.5 139.7 327.4 143.1 L 364.0 164.3" },
  { at: 3800, c: "#FF5733", d: "M 364.0 208.9 L 385.2 221.1 Q 391.0 224.5 385.2 227.9 L 339.0 254.6 Q 333.1 258.0 339.0 261.3 L 364.0 275.8" },
  { at: 4100, c: "#FF5733", d: "M 391.0 193.3 L 423.8 212.2 Q 429.7 215.6 435.5 212.2 L 466.3 194.4 Q 472.2 191.0 478.1 194.4 L 522.4 220.0" },
  { at: 4400, c: "#FF5733", d: "M 236.6 251.3 L 273.1 272.4 Q 279.0 275.8 284.9 272.4 L 296.3 265.8 Q 302.2 262.4 308.1 265.8 L 344.7 286.9" },
  { at: 5700, c: "#FF5733", d: "M 433.6 324.9 L 458.6 339.3 Q 464.4 342.7 470.4 339.3 L 501.1 321.6 Q 506.9 318.2 512.8 321.6 L 534.0 333.8" },
];

const BLOCKS = [
  { c: "#0077B6", t: "M 209.5 106.3 L 248.1 128.6 L 209.5 150.9 L 170.9 128.6 Z", l: "M 248.1 128.6 L 209.5 150.9 L 209.5 186.6 L 248.1 164.3 Z", r: "M 170.9 128.6 L 209.5 150.9 L 209.5 186.6 L 170.9 164.3 Z" },
  { c: "#00A859", t: "M 344.7 108.5 L 383.4 130.8 L 337.0 157.6 L 298.3 135.3 Z", l: "M 383.3 130.8 L 337.0 157.6 L 337.0 224.5 L 383.3 197.7 Z", r: "M 298.3 135.3 L 337.0 157.6 L 337.0 224.5 L 298.3 202.2 Z" },
  { c: "#FF5733", t: "M 383.4 206.7 L 460.6 251.3 L 402.7 284.7 L 325.4 240.1 Z", l: "M 460.6 251.3 L 402.7 284.7 L 402.7 342.7 L 460.6 309.3 Z", r: "M 325.4 240.1 L 402.7 284.7 L 402.7 342.7 L 325.4 298.1 Z" },
];

const TERMS: [number, number][] = [
  [35.7, 108.5], [89.7, 77.3], [26.0, 181.0],
  [522.4, 220.0], [534.0, 333.8], [236.5, 251.3],
];

/**
 * `still` draws the bare circuit and nothing else: no travel, no colour, no
 * timers. For a page where the drawing is there to furnish the space rather
 * than to be watched — a form, say, where the movement would pull the eye
 * off the fields.
 */
export function NetworkDiagram(
  { className = "", still = false }: { className?: string; still?: boolean },
) {
  const ref = useRef<SVGSVGElement | null>(null);
  const [pass, setPass] = useState(0);
  const [lit, setLit] = useState(0);

  useEffect(() => {
    if (still) return;              // nothing to schedule
    const el = ref.current;
    if (!el) return;

    // Anyone who asked for less motion gets the finished state, not the run.
    if (window.matchMedia?.("(prefers-reduced-motion: reduce)").matches) {
      setLit(BLOCK_AT.length);
      return;
    }

    const timers: number[] = [];
    let started = false;

    const run = () => {
      // A new key re-mounts the wires: a CSS animation that has already run
      // will not run again just because a class comes back.
      setPass((n) => n + 1);
      setLit(0);
      BLOCK_AT.forEach((at, i) => {
        timers.push(window.setTimeout(() => setLit(i + 1), at));
      });
      timers.push(window.setTimeout(() => setLit(0), LAST + HOLD));
      timers.push(window.setTimeout(run, CYCLE));
    };

    const io = new IntersectionObserver(
      ([e]) => {
        if (e.isIntersecting && !started) {
          started = true;
          run();
          io.disconnect();
        }
      },
      { threshold: 0.3 },
    );
    io.observe(el);
    return () => {
      io.disconnect();
      timers.forEach(window.clearTimeout);
    };
  }, [still]);

  return (
    <>
      <style>{CSS}</style>
      <svg
        ref={ref}
        viewBox="0 0 560 420"
        className={`cn-net ${className}`}
        role="img"
        aria-label="Work entering a system from several sources, passing through two stages, and arriving at a finished result"
        preserveAspectRatio="xMidYMid meet"
      >
        <g className="cn-wire cn-at-rest">
          {WIRES.map((w, i) => (
            <path key={i} d={w.d} />
          ))}
        </g>

        {!still && (
          <g className="cn-live" key={pass}>
            {WIRES.map((w, i) => (
              <path
                key={i}
                d={w.d}
                pathLength={1}
                stroke={w.c}
                style={{ animationDelay: `${w.at}ms` }}
              />
            ))}
          </g>
        )}

        {BLOCKS.map((b, i) => (
          <g key={i}>
            <path className="cn-face-t" d={b.t} />
            <path className="cn-face-l" d={b.l} />
            <path className="cn-face-r" d={b.r} />

            <g className={`cn-blk ${lit > i ? "cn-on" : ""}`}>
              <path d={b.t} fill={b.c} fillOpacity={0.2} />
              <path d={b.l} fill={b.c} fillOpacity={0.07} />
              <path d={b.r} fill={b.c} fillOpacity={0.12} />
              <g fill="none" stroke={b.c} strokeWidth="1.7" strokeLinejoin="round">
                <path d={b.t} />
                <path d={b.l} />
                <path d={b.r} />
              </g>
            </g>

            <g className="cn-edge">
              <path d={b.t} />
              <path d={b.l} />
              <path d={b.r} />
            </g>
          </g>
        ))}

        <g className="cn-term">
          {TERMS.map(([cx, cy], i) => (
            <ellipse key={i} cx={cx} cy={cy} rx={7.5} ry={5} />
          ))}
        </g>
      </svg>
    </>
  );
}

const CSS = `
.cn-net .cn-wire path,
.cn-net .cn-live path { fill: none; stroke-linecap: round; stroke-linejoin: round; }

.cn-net .cn-at-rest path { stroke: #CFC8BB; stroke-width: 1.7; }

/* pathLength=1 makes the dash a FRACTION of each wire however long that
   wire really is, so one pattern fits them all and the numbers are literal.
   The animation goes on the PATH: each carries its own delay, and a
   selector aimed at the group matched nothing. */
.cn-net .cn-live path {
  stroke-width: 2.4;
  stroke-dasharray: ${DASH} 1;
  stroke-dashoffset: -1;
  animation: cn-travel ${TRAVEL}ms cubic-bezier(0.45, 0, 0.3, 1) both;
}
@keyframes cn-travel {
  from { stroke-dashoffset: ${DASH}; }
  to   { stroke-dashoffset: -1; }
}

/* Light filling the block, not a switch being thrown. */
.cn-net .cn-blk { opacity: 0; transition: opacity ${FADE}ms ease-in; }
.cn-net .cn-on  { opacity: 1; transition: opacity ${RISE}ms cubic-bezier(0.33, 0, 0.25, 1); }

.cn-net .cn-face-t { fill: #F2EFE8; }
.cn-net .cn-face-l { fill: #DFD8CC; }
.cn-net .cn-face-r { fill: #E8E2D8; }
.cn-net .cn-edge path { fill: none; stroke: #CFC8BB; stroke-width: 1.7; stroke-linejoin: round; }
.cn-net .cn-term ellipse { fill: #FCFBF9; stroke: #CFC8BB; stroke-width: 1.7; }

@media (prefers-reduced-motion: reduce) {
  .cn-net .cn-live path { animation: none; stroke-dasharray: none; stroke-dashoffset: 0; }
  .cn-net .cn-blk       { transition: none; }
}
`;
